CREATE TABLE public.signup_email_proofs (user_id uuid PRIMARY KEY,email text NOT NULL,verified_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.signup_email_proofs TO service_role;
ALTER TABLE public.signup_email_proofs ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.record_signup_email_proof() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND (OLD.email_confirmed_at IS NULL OR NEW.email IS DISTINCT FROM OLD.email) THEN INSERT INTO public.signup_email_proofs(user_id,email) VALUES(NEW.id,lower(btrim(NEW.email))) ON CONFLICT(user_id) DO UPDATE SET email=excluded.email,verified_at=now(); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.record_signup_email_proof() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER bcd_signup_email_confirmation AFTER UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.record_signup_email_proof();
CREATE FUNCTION public.signup_verified_email() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT lower(btrim(u.email)) FROM auth.users u JOIN public.signup_email_proofs p ON p.user_id=u.id AND p.email=lower(btrim(u.email)) WHERE u.id=auth.uid() AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=now()) AND NOT EXISTS(SELECT 1 FROM public.account_access_revocations r WHERE r.user_id=u.id) $$;
REVOKE ALL ON FUNCTION public.signup_verified_email() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.signup_verified_email() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.ensure_member_link() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e text; n integer:=0; BEGIN e:=public.signup_verified_email(); IF e IS NULL THEN RETURN 0; END IF; WITH ins AS (INSERT INTO public.member_profiles(user_id,member_id) SELECT auth.uid(),a.member_id FROM public.member_allowed_emails a JOIN public.members_data m ON m.id=a.member_id WHERE lower(btrim(a.email))=e AND m.member_type IN ('member','lead') AND NOT EXISTS(SELECT 1 FROM public.member_profiles p WHERE p.user_id=auth.uid() AND p.member_id=a.member_id) ON CONFLICT DO NOTHING RETURNING 1) SELECT count(*) INTO n FROM ins; IF EXISTS(SELECT 1 FROM public.member_profiles p JOIN public.members_data m ON m.id=p.member_id WHERE p.user_id=auth.uid() AND m.member_type IN ('member','lead')) THEN INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'user') ON CONFLICT(user_id,role) DO NOTHING; END IF; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.ensure_member_link() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.ensure_member_link() TO authenticated;
DROP POLICY "Users can link own verified member" ON public.member_profiles;
CREATE POLICY "Users can link own verified member" ON public.member_profiles FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.member_allowed_emails a JOIN public.members_data m ON m.id=a.member_id WHERE a.member_id=member_profiles.member_id AND lower(btrim(a.email))=public.signup_verified_email() AND m.member_type IN ('member','lead'))));
ALTER TABLE public.membership_requests ADD COLUMN requester_user_id uuid;
CREATE OR REPLACE FUNCTION public.get_membership_request_status(_email text) RETURNS TABLE(status text,created_at timestamptz,has_login boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT mr.status,mr.created_at,false FROM public.membership_requests mr WHERE public.signup_verified_email() IS NOT NULL AND lower(btrim(_email))=public.signup_verified_email() AND mr.requester_user_id=auth.uid() ORDER BY mr.created_at DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.get_membership_request_status(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_membership_request_status(text) TO anon,authenticated;
CREATE FUNCTION public.bind_membership_request_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN NEW.requester_user_id:=CASE WHEN lower(btrim(NEW.email))=public.signup_verified_email() THEN auth.uid() ELSE NULL END; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.bind_membership_request_owner() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER bcd_membership_request_owner BEFORE INSERT ON public.membership_requests FOR EACH ROW EXECUTE FUNCTION public.bind_membership_request_owner();
CREATE FUNCTION public.submit_verified_external_signup(p_name text,p_type text,p_contact text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e text; oid uuid; BEGIN e:=public.signup_verified_email(); IF e IS NULL THEN RAISE EXCEPTION 'Bevestig eerst uw e-mailadres.' USING ERRCODE='42501'; END IF; IF p_name IS NULL OR p_contact IS NULL OR p_type IS NULL OR length(btrim(p_name)) NOT BETWEEN 1 AND 200 OR length(btrim(p_contact)) NOT BETWEEN 1 AND 200 OR p_type NOT IN ('bank','overheid','leverancier','anders') THEN RAISE EXCEPTION 'Ongeldige aanvraag.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0)); SELECT org_id INTO oid FROM public.external_org_users WHERE user_id=auth.uid() LIMIT 1; IF oid IS NOT NULL THEN RETURN oid; END IF; INSERT INTO public.external_organizations(name,type,contact_email,contact_name,approved) VALUES(btrim(p_name),p_type,e,btrim(p_contact),false) RETURNING id INTO oid; INSERT INTO public.external_org_users(org_id,user_id) VALUES(oid,auth.uid()); INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'extern') ON CONFLICT(user_id,role) DO NOTHING; RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.submit_verified_external_signup(text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_verified_external_signup(text,text,text) TO authenticated;
CREATE FUNCTION public.approved_supplier_owner(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.external_org_users l JOIN public.external_organizations o ON o.id=l.org_id WHERE l.user_id=auth.uid() AND o.id=p_org AND o.approved AND o.type='leverancier') $$;
REVOKE ALL ON FUNCTION public.approved_supplier_owner(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.approved_supplier_owner(uuid) TO authenticated;
DROP POLICY "Suppliers can insert own benefits" ON public.member_benefits;
DROP POLICY "Suppliers can update own benefits" ON public.member_benefits;
DROP POLICY "Suppliers can delete own benefits" ON public.member_benefits;
CREATE POLICY "Suppliers can insert own benefits" ON public.member_benefits FOR INSERT TO authenticated WITH CHECK(public.approved_supplier_owner(supplier_org_id));
CREATE POLICY "Suppliers can update own benefits" ON public.member_benefits FOR UPDATE TO authenticated USING(public.approved_supplier_owner(supplier_org_id)) WITH CHECK(public.approved_supplier_owner(supplier_org_id));
CREATE POLICY "Suppliers can delete own benefits" ON public.member_benefits FOR DELETE TO authenticated USING(public.approved_supplier_owner(supplier_org_id));